pub fn n(v:&Value,k:&str)->f64{v[k].as_f64().unwrap_or(0.)}pub fn s<'a>(v:&'a Value,k:&str)->&'a str{v[k].as_str().unwrap_or("")}pub fn round(x:f64)->f64{let n=(x*100.).round()/100.;if n==0.{0.}else{n}}pub fn near(a:f64,b:f64)->bool{(a-b).abs()<0.001}
pub fn lookup(kind:&str,name:&str)->Value{let a=catalog()[kind].as_array().unwrap();a.iter().find(|v|s(v,"name")==name).unwrap_or(&a[0]).clone()}
