pub fn validate(c:&Config)->Result<(),String>{security::validate_design(c)?;if c.garage_offset.is_some_and(|z|!z.is_finite()||!(-40.0..=140.0).contains(&z)){return Err("Choose a garage position along the side of the house.".into())}surfaces::validate(c)?;if !["R-49","R-38 HD + R-11"].contains(&c.roof_insulation.as_str()){return Err("Choose the R-49 roof batt or the two-layer roof assembly.".into())}additions::validate(c)?;pricing::validate(c)?;if !["Automatic","Left","Right"].contains(&c.garage_side.as_str()){return Err("Choose Left or Right for garage placement.".into())}if ![c.floor_live_load,c.floor_dead_load].iter().all(|v|v.is_finite()&&*v>=0.&&*v<=500.){return Err("Floor loads must be 0–500 psf.".into())}if !c.front_bearing.is_finite()||!(0.0..360.0).contains(&c.front_bearing){return Err("Choose a front-facing compass bearing from 0 to 359 degrees.".into())}if !["None","Attached","Detached"].contains(&c.garage.as_str()){return Err("Choose no garage, attached or detached.".into())}if ![piers::HELICAL,piers::CONCRETE].contains(&c.foundation.as_str()){return Err("Choose a helical pier or concrete crawlspace foundation.".into())}if !c.pier_depth.is_finite()||!(10.0..=34.0).contains(&c.pier_depth){return Err("Pier depth must be 10–34 ft.".into())}if !piers::BEAMS.contains(&c.pier_beam.as_str()){return Err("Choose a steel beam or LVL girder for the pier foundation.".into())}if ![1,2,3].contains(&c.stories)||c.active_floor>=c.stories{return Err("Choose one, two or three stories.".into())}if c.stories>=2&&(c.width<24.||(c.design_mode!="Blank slate"&&c.depth<architecture::minimum_depth(c))){return Err(format!("Two- and three-story homes start at 24 ft wide. This bedroom program needs at least {:.0} ft depth at your selected width.",architecture::minimum_depth(c)))}if !["Custom","Affordable","Premium","Blank slate"].contains(&c.design_mode.as_str()){return Err("Choose Affordable, Premium or Blank slate.".into())}if [c.labor_cost,c.land_cost,c.permit_cost,c.survey_cost].iter().any(|v|!v.is_finite()||*v<0.||*v>1e9){return Err("Project costs must be nonnegative amounts, up to $1 billion each.".into())}if !["Normal","Oversized"].contains(&c.trim_size.as_str()){return Err("Choose Normal or Oversized trim.".into())}if !(8.0..=100.0).contains(&c.width)||!(8.0..=100.0).contains(&c.depth){return Err("Width and depth must be 8–100 feet.".into())}if !near(c.width/2.,(c.width/2.).round())||!near(c.depth/2.,(c.depth/2.).round()){return Err("Use 2-foot dimension increments, from 8 to 100 feet.".into())}if ![c.ridge_vent_nfa,c.soffit_vent_nfa,c.roof_vent_nfa].iter().all(|v|v.is_finite()&&*v>0.&&*v<=1000.){return Err("Vent product net free areas must be positive, up to 1,000 square inches.".into())}if ![8.,8.09375,9.,10.].contains(&c.wall_height)||!((if architecture::preset(&c.home_style).3=="Low slope"{0.25}else{2.0})..=12.0).contains(&c.pitch)||c.bedrooms>6{return Err("Use 8–10 ft walls, a roof pitch suitable for the selected style and 0–6 bedrooms.".into())}roofing::validate(c)?;if !(0.0..=30.0).contains(&c.waste)||!(0.0..=20.0).contains(&c.tax)||c.prices.values().any(|n|!n.is_finite()||*n<0.){return Err("Check waste, tax and nonnegative unit prices.".into())}Ok(())}
/// The roof sits on the top floor; every floor below it has a floor deck above instead.
pub fn top_floor(c:&Config)->bool{c.active_floor+1>=c.stories}
/// Ids on upper floors carry a tag so saved edits stay on their floor: "-L2" (second) and "-L3" (third).
pub fn floor_tag(floor:usize)->&'static str{match floor{0=>"",1=>"-L2",_=>"-L3"}}
pub fn tag_floor(id:&str)->usize{if id.contains("-L3"){2}else if id.contains("-L2"){1}else{0}}
/// Three-story homes split bedrooms across the two upper floors (the extra one goes to the second floor).
pub fn floor_bedrooms(c:&Config,floor:usize)->usize{if c.stories<3{c.bedrooms}else if floor==2{c.bedrooms/2}else{(c.bedrooms+1)/2}}
pub fn grid(v:f64)->f64{((v/2.+1e-8).round()*2.).max(0.)}
// Scaling a stock plan can squeeze the kitchen to a 4-ft sliver. Borrow depth from a living or dining
// room that shares the kitchen's whole edge so every kitchen keeps at least 8 ft for cabinets and aisle.
fn widen_kitchens(rs:&mut [Room]){for k in 0..rs.len(){if rs[k].kind!="kitchen"{continue}for along_x in [false,true]{let short=if along_x{rs[k].w}else{rs[k].d};if short>=8.{continue}let need=8.-short;let kr=rs[k].clone();let found=(0..rs.len()).find(|&i|{let q=&rs[i];i!=k&&["living","dining","flex","studio"].contains(&q.kind.as_str())&&if along_x{near(q.z,kr.z)&&near(q.d,kr.d)&&q.w-need>=10.&&(near(q.x+q.w,kr.x)||near(kr.x+kr.w,q.x))}else{near(q.x,kr.x)&&near(q.w,kr.w)&&q.d-need>=10.&&(near(q.z+q.d,kr.z)||near(kr.z+kr.d,q.z))}});if let Some(i)=found{let before=if along_x{near(rs[i].x+rs[i].w,kr.x)}else{near(rs[i].z+rs[i].d,kr.z)};if along_x{rs[i].w-=need;rs[k].w+=need;if before{rs[k].x-=need}else{rs[i].x+=need}}else{rs[i].d-=need;rs[k].d+=need;if before{rs[k].z-=need}else{rs[i].z+=need}}}}}}
// A kitchen still too thin for a cabinet run trades places with the roomiest living space beside it;
// the sliver becomes a walk-in pantry.
fn rescue_kitchen(rs:&mut [Room]){let Some(k)=rs.iter().position(|r|r.kind=="kitchen")else{return};if rs[k].w.min(rs[k].d)>=6.{return}let kr=rs[k].clone();let touches=|q:&Room|{let xs=q.x<kr.x+kr.w-0.1&&q.x+q.w>kr.x+0.1;let zs=q.z<kr.z+kr.d-0.1&&q.z+q.d>kr.z+0.1;(xs&&(near(q.z+q.d,kr.z)||near(kr.z+kr.d,q.z)))||(zs&&(near(q.x+q.w,kr.x)||near(kr.x+kr.w,q.x)))};let best=(0..rs.len()).filter(|&i|i!=k&&["dining","flex"].contains(&rs[i].kind.as_str())&&rs[i].w.min(rs[i].d)>=8.&&!rs[i].name.to_lowercase().contains("laundry")).max_by(|&a,&b|((touches(&rs[a]) as u8 as f64)*1e6+rs[a].w*rs[a].d).total_cmp(&((touches(&rs[b]) as u8 as f64)*1e6+rs[b].w*rs[b].d)));if let Some(i)=best{let(name,kind)=(rs[i].name.clone(),rs[i].kind.clone());let _=(name,kind);rs[i].kind="kitchen".into();rs[i].name="Kitchen".into();rs[k].kind="flex".into();rs[k].name="Walk-in pantry".into();}}
fn base_layout(c:&Config)->(Vec<Room>,Value){if c.design_mode=="Blank slate"{let rs=vec![Room{id:format!("blank{}",floor_tag(c.active_floor)),name:"Empty floor".into(),kind:"blank".into(),x:0.,z:0.,w:c.width,d:c.depth}];return (rs.clone(),json!({"rooms":rs,"style":{"name":"Blank slate","description":"An empty shell for your own wall and item layout."},"bedrooms":0,"baths":0,"gridFeet":2,"program":"Blank slate","note":"Click the floor to add walls and items. Click walls to add doors or windows. Complete the layout before code and engineering review."}));}if c.catalog_plan{return heritage::layout(c)}if let Some(plan)=architecture::floor_layout(c){return plan}
 let style=lookup("layoutStyles",&c.layout);let u=c.width.max(c.depth);let v=c.width.min(c.depth);let micro=u*v<144.||u<17.;let compact=v<24.||u<32.;let a=plans().as_array().unwrap();
 let score=|p:&Value|{let pw=n(p,"w");let pd=n(p,"d");let pm=pw*pd<144.||pw<17.;let pc=pd<24.||pw<32.;(if pm!=micro||!micro&&pc!=compact{1000.}else{0.})+(u/pw).ln().abs()+(v/pd).ln().abs()};
 let p=a.iter().filter(|p|n(p,"index")==n(&style,"index")&&n(p,"beds")==c.bedrooms as f64).min_by(|a,b|score(a).total_cmp(&score(b))).unwrap();let mut rs:Vec<Room>=serde_json::from_value(p["rooms"].clone()).unwrap();
 for r in &mut rs{let x=grid(r.x*u/n(p,"w")).min(u);let z=grid(r.z*v/n(p,"d")).min(v);let end_x=grid((r.x+r.w)*u/n(p,"w")).min(u);let end_z=grid((r.z+r.d)*v/n(p,"d")).min(v);r.x=x;r.z=z;r.w=end_x-x;r.d=end_z-z;if r.kind=="bedroom"&&(r.w<8.||r.d<8.||r.w*r.d<70.){r.kind="flex".into();r.name="Flexible room".into();}if c.depth>c.width{std::mem::swap(&mut r.x,&mut r.z);std::mem::swap(&mut r.w,&mut r.d);}}widen_kitchens(&mut rs);rescue_kitchen(&mut rs);
 rs.retain(|r|r.w>=2.&&r.d>=2.);let mut out=p.clone();out["style"]=style;out["bedrooms"]=json!(rs.iter().filter(|r|r.kind=="bedroom").count());out["baths"]=json!(rs.iter().filter(|r|r.kind=="bath").count());out["rooms"]=json!(rs);out["gridFeet"]=json!(2);out["note"]=json!(format!("{} Rooms use nominal 2-foot grid dimensions; finishes reduce clear interior space.",s(p,"note")));(rs,out)
}

