pub fn layout(c:&Config)->(Vec<Room>,Value){let below=floor_bedrooms(c,1);let split;let c=if c.stories==3{split=Config{bedrooms:floor_bedrooms(c,c.active_floor),..c.clone()};&split}else{c};let(mut rs,mut out)=base_layout(c);heritage::foyer(c,&mut rs);if let Some(stair)=stairs::room(c){rs.clear();for(i,(x,z,w,d))in [(0.,0.,c.width,stair.z),(0.,stair.z+stair.d,c.width,c.depth-stair.z-stair.d),(0.,stair.z,stair.x,stair.d),(stair.x+stair.w,stair.z,c.width-stair.x-stair.w,stair.d)].into_iter().enumerate(){if w>0.1&&d>0.1{rs.push(Room{id:format!("blank{}-{}",c.active_floor,i),name:"Empty floor".into(),kind:"blank".into(),x,z,w,d});}}rs.push(stair);}if c.stories==3&&c.active_floor>0{let mut kept=0;for r in &mut rs{if r.kind=="bedroom"{kept+=1;if kept>c.bedrooms{r.kind="flex".into();r.name=if c.active_floor==2{"Bonus room"}else{"Flexible room"}.into();}}}if c.stories==3&&c.active_floor==2{let mut k=below;for r in rs.iter_mut().filter(|r|r.kind=="bedroom"){k+=1;r.name=format!("Bedroom {}",k);}}}out["rooms"]=json!(rs);out["bedrooms"]=json!(rs.iter().filter(|r|r.kind=="bedroom").count());out["baths"]=json!(rs.iter().filter(|r|r.kind=="bath").count());out["gridFeet"]=json!(2);out["foyer"]=json!(rs.iter().any(|r|r.kind=="foyer"));(rs,out)}

#[cfg(target_arch="wasm32")]#[wasm_bindgen]pub fn apply_texture(input:&str){if input.len()<=201_000{ui::texture(input)}}
